/**
 * Starts the EXPRESS-003 app on a real port so you can send requests by hand.
 * Run: npm run dev:express:3   (restarts on every save, which also resets the tasks)
 * Do not edit this file; write your solution in task3.ts.
 */
import type { NextFunction, Request, Response } from "express";
import { createApp, type Task } from "./task3";

const PORT = Number(process.env.PORT ?? 3000);

const sampleTasks: Task[] = [
  { id: "t1", title: "Write notes", priority: "high", status: "todo", createdAt: "2026-03-01T10:00:00.000Z", updatedAt: "2026-03-01T10:00:00.000Z" },
  { id: "t2", title: "Buy milk", priority: "medium", status: "done", createdAt: "2026-03-01T11:00:00.000Z", updatedAt: "2026-03-02T09:00:00.000Z" },
  { id: "t3", title: "Call mom", priority: "low", status: "todo", createdAt: "2026-03-01T12:00:00.000Z", updatedAt: "2026-03-01T12:00:00.000Z" },
];

const app = createApp(sampleTasks);

// Runs only for errors your code does not handle itself: prints the full error
// in this terminal and returns it in the response, so a 500 shows what broke.
app.use((err: unknown, req: Request, res: Response, _next: NextFunction) => {
  console.error(`\n500 on ${req.method} ${req.originalUrl}\n`, err);
  const message = err instanceof Error ? err.message : String(err);
  res.status(500).json({ unhandledError: message });
});

app.listen(PORT, () => {
  console.log(`EXPRESS-003 running on http://localhost:${PORT} with tasks t1, t2, t3`);
  console.log("Send requests from src/express/task3/requests.http");
});
